const CIUDADES_TEXTO = 'Bogota, Medellin, Rionegro, Cali, Barranquilla, Cartagena, Pereira';
const resultados = [];

for (const item of $input.all()) {
  const e = item.json;

  // Intentar internalDate primero, luego payload.headers como fallback
  let fechaReal = e.internalDate ? new Date(parseInt(e.internalDate)).toISOString() : null;
  if (!fechaReal && e.payload && e.payload.headers) {
    const dh = e.payload.headers.find(h => h.name === 'Date' || h.name === 'date');
    if (dh && dh.value) {
      const parsed = new Date(dh.value);
      if (!isNaN(parsed.getTime())) fechaReal = parsed.toISOString();
    }
  }

  const fromReal = e.from || e.From || e.sender || '';
  const texto = `${e.subject || e.Subject || ''} ${e.text || e.snippet || e.body || ''}`.substring(0, 1500);

  const contenido = [];
  const binary = item.binary || {};
  const adjuntos = Object.keys(binary);

  for (const key of adjuntos) {
    const adj = binary[key];
    const mimeType = adj.mimeType || '';
    if (mimeType === 'application/pdf') {
      contenido.push({
        type: 'document',
        source: {
          type: 'base64',
          media_type: 'application/pdf',
          data: adj.data
        }
      });
    }
  }

  contenido.push({
    type: 'text',
    text: `Eres asistente de RRHH de Asignar SAS, empresa de servicios temporales en Colombia.
Analiza este email y responde UNICAMENTE con JSON valido, sin texto adicional ni markdown.

CONTEXTO: Estos emails provienen de una limpieza de la bandeja marketingdigital@asignar.com.co. Son hojas de vida y postulaciones recibidas en 2025 que no fueron procesadas en su momento.

Primero determina si este email es una postulacion de empleo o envio de hoja de vida.
SI es postulacion: alguien enviando su CV, preguntando por vacantes, adjuntando hoja de vida, mencionando que quiere trabajar.
NO es postulacion: facturas, newsletters, notificaciones de plataformas, correos de trabajo del equipo, alertas de sistemas, confirmaciones de compra.

Si NO es postulacion, responde SOLO:
{ "es_postulacion": false, "accion": "dejar_inbox", "motivo": "razon breve" }

Si SI es postulacion, busca la ciudad en TODO el contenido: asunto, cuerpo del email Y en los documentos adjuntos.
Ciudades validas (devuelve el nombre EXACTAMENTE como aparece en esta lista): ${CIUDADES_TEXTO}

Email:
- Asunto: ${e.subject || e.Subject || '(sin asunto)'}
- Remitente: ${fromReal || '(desconocido)'}
- Contenido: ${texto}

Si es postulacion, devuelve:
{
  "es_postulacion": true,
  "ciudad": "nombre EXACTO de la lista o null si no aparece ninguna",
  "cargo": "cargo mencionado o null",
  "tiene_hoja_de_vida": true o false,
  "accion": "reenviar" o "revisar_manual",
  "motivo": "razon breve",
  "confianza": "alta" o "media" o "baja"
}

REGLAS CRITICAS:
- ciudad debe ser EXACTAMENTE uno de: ${CIUDADES_TEXTO}
- Busca la ciudad en el email Y en los documentos adjuntos
- Solo null si NO aparece ninguna ciudad en ninguna parte
- accion reenviar cuando ciudad identificada, revisar_manual cuando ciudad es null`
  });

  resultados.push({
    json: {
      emailData: { ...e, date: fechaReal, fromResuelto: fromReal },
      apiBodyObj: {
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 400,
        messages: [{ role: 'user', content: contenido }]
      }
    }
  });
}

return resultados;

const prepItems = $('Preparar Prompt').all();
const httpItems = $input.all();
const FECHA_CORTE = new Date('2025-01-01T00:00:00Z');
const FECHA_ANTIGUA = new Date('2026-01-01T00:00:00Z');
const EMAIL_FALLBACK = 'contratacion2@asignar.com.co';

function getEmailForCiudad(ciudad) {
  if (!ciudad) return null;
  const map = {
    'bogota':        'reclutamientobog4@asignar.com.co',
    'medellin':      'seleccion4@asignar.com.co',
    'rionegro':      'seleccion4@asignar.com.co',
    'cali':          'seleccioncali@asignar.com.co',
    'barranquilla':  'seleccionbarranquilla@asignar.com.co',
    'cartagena':     'seleccioncartagena407@gmail.com',
    'pereira':       'generalistapereira@asignar.com.co'
  };
  let s = ciudad;
  try { s = decodeURIComponent(escape(ciudad)); } catch(e) {}
  s = s.toLowerCase().trim()
    .replace(/[aáàäâã]/g, 'a')
    .replace(/[eéèëê]/g, 'e')
    .replace(/[iíìïî]/g, 'i')
    .replace(/[oóòöôõ]/g, 'o')
    .replace(/[uúùüû]/g, 'u')
    .replace(/ñ/g, 'n');
  return map[s] || null;
}

function extraerJSON(text) {
  if (!text) throw new Error('Respuesta vacia');
  let limpio = text.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  const inicio = limpio.indexOf('{');
  const fin = limpio.lastIndexOf('}');
  if (inicio !== -1 && fin > inicio) {
    limpio = limpio.substring(inicio, fin + 1);
  }
  return JSON.parse(limpio);
}

const resultados = [];
for (let i = 0; i < httpItems.length; i++) {
  const httpResp = httpItems[i].json;
  const origEmail = prepItems[i].json.emailData;
  const fechaResuelta = origEmail.date || (origEmail.internalDate ? new Date(parseInt(origEmail.internalDate)).toISOString() : '');
  const fromResuelta = origEmail.fromResuelto || origEmail.from || origEmail.From || '';

  let cl = {};
  let rawClaude = '';
  try {
    if (!httpResp.content || !httpResp.content[0]) {
      throw new Error('Sin content en respuesta API: ' + JSON.stringify(httpResp).substring(0, 300));
    }
    rawClaude = httpResp.content[0].text || '';
    cl = extraerJSON(rawClaude);
  } catch(err) {
    cl = { es_postulacion: false, accion: 'dejar_inbox', motivo: 'ERROR_PARSEO: ' + err.message };
  }

  const fechaEmail = new Date(fechaResuelta);
  const fechaValida = !isNaN(fechaEmail.getTime());
  const esAntiguo = fechaValida && fechaEmail < FECHA_ANTIGUA;
  const yearEmail = fechaValida ? fechaEmail.getFullYear() : 'desconocido';

  if (!cl.es_postulacion) {
    resultados.push({ json: {
      id: origEmail.id,
      fecha: fechaResuelta,
      asunto: origEmail.subject || origEmail.Subject || '(sin asunto)',
      remitente: fromResuelta,
      esPostulacion: false,
      motivoClaude: cl.motivo,
      rawClaude: rawClaude.substring(0, 500),
      accionFinal: 'DEJAR EN INBOX',
      emailDestino: 'sin accion',
      categoria: 'dejar_inbox',
      esAntiguo,
      yearEmail,
      origSubject: origEmail.subject || origEmail.Subject || '(sin asunto)',
      origFrom: fromResuelta,
      origDate: fechaResuelta,
      origBody: origEmail.text || origEmail.snippet || '(sin contenido)'
    }});
    continue;
  }

  const esReciente = !fechaValida || fechaEmail >= FECHA_CORTE;
  const emailCiudad = getEmailForCiudad(cl.ciudad);
  let emailDestino = '', categoria = '';

  if (!esReciente) {
    categoria = 'archivar';
    emailDestino = 'ARCHIVAR';
  } else if (cl.ciudad && emailCiudad) {
    categoria = 'reenviar';
    emailDestino = emailCiudad;
  } else {
    categoria = 'revisar_manual';
    emailDestino = EMAIL_FALLBACK;
  }

  const accionFinal = categoria === 'archivar'
    ? 'ARCHIVAR (pre-2025)'
    : categoria === 'reenviar'
      ? 'REENVIAR -> ' + emailDestino
      : 'REVISAR MANUAL -> ' + emailDestino;

  resultados.push({ json: {
    id: origEmail.id,
    fecha: fechaResuelta,
    asunto: origEmail.subject || origEmail.Subject || '(sin asunto)',
    remitente: fromResuelta,
    esPostulacion: true,
    ciudadDetectada: cl.ciudad || 'No detectada',
    cargo: cl.cargo || '(no especificado)',
    tieneHV: cl.tiene_hoja_de_vida,
    confianza: cl.confianza,
    motivoClaude: cl.motivo,
    rawClaude: rawClaude.substring(0, 500),
    esReciente,
    esAntiguo,
    yearEmail,
    accionFinal,
    emailDestino,
    categoria,
    origSubject: origEmail.subject || origEmail.Subject || '(sin asunto)',
    origFrom: fromResuelta,
    origDate: fechaResuelta,
    origBody: origEmail.text || origEmail.snippet || '(sin contenido)'
  }});
}
return resultados;

const getItem = $input.item;
const parsearItems = $("Parsear Respuesta").all();
const currentId = getItem.json.id;
const parsearItem = parsearItems.find(p => p.json.id === currentId);
if (!parsearItem) {
  return { json: getItem.json };
}
const binaryData = getItem.binary || {};
const keys = Object.keys(binaryData);
const mergedJson = { ...parsearItem.json };
const origText = getItem.json.text || getItem.json.snippet || '(sin contenido)';
const origHtml = getItem.json.html || '';
mergedJson.origBodyFull = origText;
mergedJson.origHtmlFull = origHtml;
if (keys.length > 0) {
  const newBinary = {};
  const attachmentProps = [];
  keys.forEach((key, i) => {
    const propName = `attachment_${i}`;
    newBinary[propName] = binaryData[key];
    attachmentProps.push(propName);
  });
  mergedJson.attachmentCount = keys.length;
  mergedJson.attachmentProperties = attachmentProps;
  return { json: mergedJson, binary: newBinary };
}
mergedJson.attachmentCount = 0;
mergedJson.attachmentProperties = [];
return { json: mergedJson };

